theorem TriangleEmpty.child {depth : ℕ} {p : ℕ → Point} {S : Finset ℕ}
    (h : TriangleEmpty (depth + 1) p S) {r : ℕ} (hr : r < 2) :
    TriangleEmpty depth (fun i => p (2 * i + r)) (childIndices S r)

theorem IsHorton.above_indices {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {a b t : ℕ}
    (hab : a < b) (hb : b < 2 ^ (depth + 1)) (ht : t < 2 ^ (depth + 1))
    (ha0 : a % 2 = 0) (hb0 : b % 2 = 0) (ht1 : t % 2 = 1) :
    0 < orient (p a) (p b) (p t)

theorem IsHorton.below_indices {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {a b t : ℕ}
    (hab : a < b) (hb : b < 2 ^ (depth + 1)) (ht : t < 2 ^ (depth + 1))
    (ha1 : a % 2 = 1) (hb1 : b % 2 = 1) (ht0 : t % 2 = 0) :
    orient (p a) (p b) (p t) < 0

theorem IsHorton.orient_ne_zero_sorted {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton depth p) {a b c : ℕ}
    (hab : a < b) (hbc : b < c) (hc : c < 2 ^ depth) :
    orient (p a) (p b) (p c) ≠ 0

theorem IsHorton.orient_ne_zero_of_lt {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton depth p) {a b c : ℕ}
    (_ha : a < 2 ^ depth) (hb : b < 2 ^ depth) (hc : c < 2 ^ depth)
    (hab : a < b) (hac : a ≠ c) (hbc : b ≠ c) :
    orient (p a) (p b) (p c) ≠ 0

theorem IsHorton.orient_ne_zero {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton depth p) {a b c : ℕ}
    (ha : a < 2 ^ depth) (hb : b < 2 ^ depth) (hc : c < 2 ^ depth)
    (hab : a ≠ b) (hac : a ≠ c) (hbc : b ≠ c) :
    orient (p a) (p b) (p c) ≠ 0

theorem IsHorton.above {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {i j t : ℕ}
    (hij : i < j) (hj : j < 2 ^ depth) (ht : t < 2 ^ depth) :
    0 < orient (p (2 * i)) (p (2 * j)) (p (2 * t + 1))

theorem IsHorton.below {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {i j t : ℕ}
    (hij : i < j) (hj : j < 2 ^ depth) (ht : t < 2 ^ depth) :
    orient (p (2 * i + 1)) (p (2 * j + 1)) (p (2 * t)) < 0

theorem upperVisible_odd {p : ℕ → Point} {i j : ℕ}
    (h : UpperVisible p (2 * i + 1) (2 * j + 1)) :
    UpperVisible (oddPoints p) i j

theorem lowerVisible_even {p : ℕ → Point} {i j : ℕ}
    (h : LowerVisible p (2 * i) (2 * j)) :
    LowerVisible (evenPoints p) i j

theorem IsHorton.not_upperVisible_even {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {i j : ℕ}
    (hij : i < j) (hj : j < 2 ^ depth) :
    ¬UpperVisible p (2 * i) (2 * j)

theorem IsHorton.not_lowerVisible_odd {depth : ℕ} {p : ℕ → Point}
    (h : IsHorton (depth + 1) p) {i j : ℕ}
    (hij : i < j) (hj : j < 2 ^ depth) :
    ¬LowerVisible p (2 * i + 1) (2 * j + 1)
